\tilde{s}[f] = 2i P\int_{t= -\infty}^{+\infty} \frac{f(t)}{t} dt = 2i \lim_{\epsilon\rightarrow 0} \left( \int_{t= -\infty}^{\epsilon} \frac{f(t)}{t} dt + \int_{t= +\epsilon}^{+\infty} \frac{f(t)}{t} dt\right)
\end{align} 
